package dev.raf.radar;
import org.junit.*;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import org.json.*;
public class SourceQueueTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void firstSyncRenameAndMovePersistButUnchangedNamesDoNotResend()throws Exception{AtomicLong now=new AtomicLong(1000);File file=new File(temp.newFolder(),"sources.json");SourceQueue q=new SourceQueue(file,now::get);Point p=new Point("one","Родник",55,61,false);q.synchronize(1,Arrays.asList(p,new Point("me","Моя геопозиция",55,61,true)));JSONArray first=q.batch(1);assertEquals(1,first.length());q.acknowledge(1,first);q.synchronize(1,Collections.singletonList(p));assertEquals(0,q.batch(1).length());p.name="Парковый";now.incrementAndGet();q.synchronize(1,Collections.singletonList(p));SourceQueue reopened=new SourceQueue(file,now::get);assertEquals("Парковый",reopened.batch(1).getJSONObject(0).getString("name"));reopened.acknowledge(1,first);assertEquals(1,reopened.batch(1).length());JSONArray renamed=reopened.batch(1);reopened.acknowledge(1,renamed);p.lat=56;reopened.synchronize(1,Collections.singletonList(p));assertEquals(56,reopened.batch(1).getJSONObject(0).getDouble("lat"),0);assertEquals(0,reopened.batch(2).length());}
 @Test public void namesAreScopedToOwnerAndAcknowledgmentsCannotClearAnotherOwner()throws Exception{SourceQueue q=new SourceQueue(new File(temp.newFolder(),"sources.json"),()->1000);Point p=new Point("same","A",55,61,false);q.synchronize(1,Collections.singletonList(p));q.synchronize(2,Collections.singletonList(p));q.acknowledge(1,q.batch(1));assertEquals(1,q.batch(2).length());assertEquals(0,q.batch(1).length());}
 @Test public void legacyInvalidMetadataCannotBlockValidObservationBatches()throws Exception{SourceQueue q=new SourceQueue(new File(temp.newFolder(),"sources.json"),()->1000);Point longName=new Point("long","x".repeat(90),55,61,false);Point bad=new Point("bad","Invalid",Double.NaN,61,false);q.synchronize(1,Arrays.asList(longName,bad));JSONArray rows=q.batch(1);assertEquals(1,rows.length());assertEquals(80,rows.getJSONObject(0).getString("name").length());}
}
